def countSubMultisets(nums, lo, hi):
    MOD = 1_000_000_007
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    dp = [0] * (hi + 1)
    dp[0] = cnt.pop(0, 0) + 1
    for v, c in cnt.items():
        if v > hi:
            continue
        new = dp[:]
        step = (c + 1) * v
        for s in range(v, hi + 1):
            t = new[s - v] + dp[s]
            if s >= step:
                t -= dp[s - step]
            new[s] = t % MOD
        dp = new
    return sum(dp[lo:hi + 1]) % MOD
